/* Moto Log service worker — generated by tools/make-sw.cjs. Do not edit. */
const CACHE = "moto-log-705e23f82cfd";
const PRECACHE = [
  "./",
  "./apple-touch-icon.f92e4254.png",
  "./favicon-64.d6cae78a.png",
  "./icon-192.b9ad1e7f.png",
  "./icon-512.01151443.png",
  "./icon-maskable-512.27695370.png",
  "./index.html",
  "./manifest.webmanifest",
  "./mlb.0ba9a045.css",
  "./mlb.cd24f707.js"
];

self.addEventListener("install", event => {
  event.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)));
  // Deliberately no skipWaiting: a new build takes over on the next launch
  // rather than reloading the page while you are part-way through an entry.
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;

  // Navigations always resolve to the app shell, so a deep link or a shortcut
  // still opens offline.
  if (req.mode === "navigate") {
    event.respondWith((async () => {
      const cached = await caches.match("/moto/", { ignoreSearch: true });
      if (cached) return cached;
      try { return await fetch(req); }
      catch { return new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } }); }
    })());
    return;
  }

  // Everything else is content-hashed, so cache-first is safe.
  event.respondWith((async () => {
    const cached = await caches.match(req);
    if (cached) return cached;
    try {
      const res = await fetch(req);
      if (res.ok && res.type === "basic") {
        const clone = res.clone();
        caches.open(CACHE).then(c => c.put(req, clone));
      }
      return res;
    } catch (err) {
      return cached || Response.error();
    }
  })());
});
